export function MaximumNumberOfPointsWithCostProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: MaximumNumberOfPointsWithCostTemplates,
      generateSteps: (t: any) => {
        const recorded = generateMaximumNumberOfPointsWithCostSteps(t) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Maximum Number of Points with Cost"
      slug="maximum-number-of-points-with-cost"
      approaches={approaches}
      presets={MaximumNumberOfPointsWithCostPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

