function generateNumberOfWaysToPaintN3GridSteps(__inputArg: any): any[] {
  
  return (function(e: any) {
let t=e.n,r=new StepRecorder({n:t,row:void 0,three:void 0,two:void 0,newThree:void 0,newTwo:void 0,result:void 0},{});r.record("-",`Paint an ${t}\xd73 grid with 3 colors so no two adjacent cells share a color`);let n=6,i=6;r.update_variable("row",1),r.update_variable("three",n),r.update_variable("two",i),r.record("init","Row 1: 6 three-color patterns (abc, like R-Y-G) and 6 two-color patterns (aba, like R-Y-R)");for(let e=1;e<t;e++){let t=e+1;r.update_variable("row",t),r.add_conditional("for_loop",!0),r.record("loop",`Row ${t}: extend every pattern of row ${e} with a compatible new row`);let o=(2*n+2*i)%0x3b9aca07;r.update_variable("newThree",o),r.record("compute_three",`newThreeColor = 2\xd7${n} + 2\xd7${i} = ${o} (each abc row allows 2 abc rows on top, each aba allows 2)`);let a=(2*n+3*i)%0x3b9aca07;r.update_variable("newTwo",a),r.record("compute_two",`newTwoColor = 2\xd7${n} + 3\xd7${i} = ${a} (each abc row allows 2 aba rows on top, each aba allows 3)`),n=o,i=a,r.update_variable("three",n),r.update_variable("two",i),r.record("update",`Row ${t} settled: threeColor = ${n}, twoColor = ${i}`)}let a=(n+i)%0x3b9aca07;return r.update_variable("result",a),r.add_conditional("for_loop",!1),r.record("compute_result",`result = (threeColor + twoColor) % MOD = ${n} + ${i} = ${a}`),r.record("complete",`Done: ${a} ways to paint the ${t}\xd73 grid`),r.getSteps()
  })(__inputArg);
}

export function NumberOfWaysToPaintN3GridProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: NumberOfWaysToPaintN3GridTemplates,
      generateSteps: (e: any) => {
        const recorded = generateNumberOfWaysToPaintN3GridSteps(e) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Number of Ways to Paint N × 3 Grid"
      slug="number-of-ways-to-paint-n-3-grid"
      approaches={approaches}
      presets={NumberOfWaysToPaintN3GridPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

