export function NumberOfLongestIncreasingSubsequenceProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: NumberOfLongestIncreasingSubsequenceTemplates,
      generateSteps: (e: any) => {
        const recorded = generateNumberOfLongestIncreasingSubsequenceSteps(e) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Number of Longest Increasing Subsequence"
      slug="number-of-longest-increasing-subsequence"
      approaches={approaches}
      presets={NumberOfLongestIncreasingSubsequencePresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

