export function LongestIncreasingPathInAMatrixProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: LongestIncreasingPathInAMatrixTemplates,
      generateSteps: (e: any) => {
        const recorded = generateLongestIncreasingPathInAMatrixSteps(e) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Longest Increasing Path in a Matrix"
      slug="longest-increasing-path-in-a-matrix"
      approaches={approaches}
      presets={LongestIncreasingPathInAMatrixPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

