    "code": "function colorTheGrid(m: number, n: number): number {\n    const MOD = 1e9 + 7;\n    const grid: number[][] = Array.from({ length: m }, () => Array(n).fill(-1));\n\n    const backtrack = (r: number, c: number): number => {\n        if (c === n) return 1;\n\n        let nextR = r + 1, nextC = c;\n        if (nextR === m) { nextR = 0; nextC = c + 1; }\n\n        let count = 0;\n        for (let color = 0; color < 3; color++) {\n            if (r > 0 && grid[r - 1][c] === color) continue;\n            if (c > 0 && grid[r][c - 1] === color) continue;\n\n            grid[r][c] = color;\n            count = (count + backtrack(nextR, nextC)) % MOD;\n            grid[r][c] = -1;\n        }\n        return count;\n    };\n\n    return backtrack(0, 0);\n}",
