    "code": "func minCost(grid [][]int, k int) int {\n    m, n := len(grid), len(grid[0])\n    const inf = math.MaxInt32\n\n    // dist[r][c][t] = min cost to reach (r,c) with t teleports remaining\n    dist := make([][][]int, m)\n    for i := range dist {\n        dist[i] = make([][]int, n)\n        for j := range dist[i] {\n            dist[i][j] = make([]int, k+1)\n            for t := range dist[i][j] {\n                dist[i][j][t] = inf\n            }\n        }\n    }\n\n    dist[0][0][k] = 0\n    // Min-heap: {cost, row, col, teleports_remaining}\n    h := &minHeap{{0, 0, 0, k}}\n    heap.Init(h)\n\n    for h.Len() > 0 {\n        curr := heap.Pop(h).([4]int)\n        cost, r, c, t := curr[0], curr[1], curr[2], curr[3]\n\n        if r == m-1 && c == n-1 {\n            return cost\n        }\n        if cost > dist[r][c][t] {\n            continue\n        }\n\n        // Normal moves\n        dirs := [][2]int{{1, 0}, {0, 1}}\n        for _, d := range dirs {\n            nr, nc := r+d[0], c+d[1]\n            if nr < m && nc < n {\n                newCost := cost + grid[nr][nc]\n                if newCost < dist[nr][nc][t] {\n                    dist[nr][nc][t] = newCost\n                    heap.Push(h, [4]int{newCost, nr, nc, t})\n                }\n            }\n        }\n\n        // Teleportation\n        if t > 0 {\n            for i := 0; i < m; i++ {\n                for j := 0; j < n; j++ {\n                    if grid[i][j] <= grid[r][c] {\n                        if cost < dist[i][j][t-1] {\n                            dist[i][j][t-1] = cost\n                            heap.Push(h, [4]int{cost, i, j, t - 1})\n                        }\n                    }\n                }\n            }\n        }\n    }\n\n    return -1\n}\n\ntype minHeap [][4]int\nfunc (h minHeap) Len() int           { return len(h) }\nfunc (h minHeap) Less(i, j int) bool { return h[i][0] < h[j][0] }\nfunc (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }\nfunc (h *minHeap) Push(x interface{}) { *h = append(*h, x.([4]int)) }\nfunc (h *minHeap) Pop() interface{} {\n    old := *h\n    x := old[len(old)-1]\n    *h = old[:len(old)-1]\n    return x\n}",
