export function MinimumCostPathWithTeleportationsProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: MinimumCostPathWithTeleportationsTemplates,
      generateSteps: (t: any) => {
        const recorded = generateMinimumCostPathWithTeleportationsSteps(t) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Minimum Cost Path with Teleportations"
      slug="minimum-cost-path-with-teleportations"
      approaches={approaches}
      presets={MinimumCostPathWithTeleportationsPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

