export function MinimumDifficultyOfAJobScheduleProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: MinimumDifficultyOfAJobScheduleTemplates,
      generateSteps: (e: any) => {
        const recorded = generateMinimumDifficultyOfAJobScheduleSteps(e) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Minimum Difficulty of a Job Schedule"
      slug="minimum-difficulty-of-a-job-schedule"
      approaches={approaches}
      presets={MinimumDifficultyOfAJobSchedulePresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

