export function MinimumDeletionsToMakeStringBalancedProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: MinimumDeletionsToMakeStringBalancedTemplates,
      generateSteps: (e: any) => {
        const recorded = generateMinimumDeletionsToMakeStringBalancedSteps(e) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Minimum Deletions to Make String Balanced"
      slug="minimum-deletions-to-make-string-balanced"
      approaches={approaches}
      presets={MinimumDeletionsToMakeStringBalancedPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

