export function NumberOfWaysToArriveAtDestinationProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: NumberOfWaysToArriveAtDestinationTemplates,
      generateSteps: (e: any) => {
        const recorded = generateNumberOfWaysToArriveAtDestinationSteps(e) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Number of Ways to Arrive at Destination"
      slug="number-of-ways-to-arrive-at-destination"
      approaches={approaches}
      presets={NumberOfWaysToArriveAtDestinationPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

