export function KnightProbabilityInChessboardProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: KnightProbabilityInChessboardTemplates,
      generateSteps: (e: any) => {
        const recorded = generateKnightProbabilityInChessboardSteps(e) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Knight Probability in Chessboard"
      slug="knight-probability-in-chessboard"
      approaches={approaches}
      presets={KnightProbabilityInChessboardPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

