export function BestTimeToBuyAndSellStockWithCooldownProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: BestTimeToBuyAndSellStockWithCooldownTemplates,
      generateSteps: (e: any) => {
        const recorded = generateBestTimeToBuyAndSellStockWithCooldownSteps(e) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Best Time to Buy and Sell Stock with Cooldown"
      slug="best-time-to-buy-and-sell-stock-with-cooldown"
      approaches={approaches}
      presets={BestTimeToBuyAndSellStockWithCooldownPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}

