    "code": "public class Solution {\n    private int[][] trie;\n    private bool[] isEnd;\n    private int trieIdx;\n\n    public IList<string> FindAllConcatenatedWordsInADict(string[] words) {\n        int totalChars = 0;\n        foreach (string w in words) totalChars += w.Length;\n        trie = new int[totalChars + 1][];\n        isEnd = new bool[totalChars + 1];\n        trieIdx = 0;\n\n        for (int i = 0; i <= totalChars; i++) {\n            trie[i] = new int[26];\n            Array.Fill(trie[i], -1);\n        }\n\n        foreach (string word in words) {\n            if (word.Length > 0) InsertTrie(word);\n        }\n\n        List<string> result = new List<string>();\n        foreach (string word in words) {\n            if (word.Length > 0 && Dfs(word, 0, 0, new bool[word.Length])) {\n                result.Add(word);\n            }\n        }\n        return result;\n    }\n\n    private void InsertTrie(string word) {\n        int node = 0;\n        foreach (char c in word) {\n            int idx = c - 'a';\n            if (trie[node][idx] == -1) {\n                trieIdx++;\n                trie[node][idx] = trieIdx;\n            }\n            node = trie[node][idx];\n        }\n        isEnd[node] = true;\n    }\n\n    private bool Dfs(string word, int pos, int count, bool[] visited) {\n        if (pos == word.Length) {\n            return count >= 2;\n        }\n        if (visited[pos]) return false;\n        visited[pos] = true;\n\n        int node = 0;\n        for (int i = pos; i < word.Length; i++) {\n            int c = word[i] - 'a';\n            if (trie[node][c] == -1) break;\n            node = trie[node][c];\n            if (isEnd[node]) {\n                if (Dfs(word, i + 1, count + 1, visited)) {\n                    return true;\n                }\n            }\n        }\n        return false;\n    }\n}",
