    "code": "type TrieNode struct {\n    children [26]*TrieNode\n    isEnd    bool\n}\n\nfunc findAllConcatenatedWordsInADict(words []string) []string {\n    root := &TrieNode{}\n\n    // Build trie\n    for _, word := range words {\n        if len(word) == 0 {\n            continue\n        }\n        node := root\n        for _, ch := range word {\n            idx := ch - 'a'\n            if node.children[idx] == nil {\n                node.children[idx] = &TrieNode{}\n            }\n            node = node.children[idx]\n        }\n        node.isEnd = true\n    }\n\n    var result []string\n    for _, word := range words {\n        if len(word) == 0 {\n            continue\n        }\n        visited := make([]bool, len(word))\n        if dfs(word, 0, 0, visited, root) {\n            result = append(result, word)\n        }\n    }\n    return result\n}\n\nfunc dfs(word string, pos, count int, visited []bool, root *TrieNode) bool {\n    if pos == len(word) {\n        return count >= 2\n    }\n    if visited[pos] {\n        return false\n    }\n    visited[pos] = true\n\n    node := root\n    for i := pos; i < len(word); i++ {\n        idx := word[i] - 'a'\n        if node.children[idx] == nil {\n            break\n        }\n        node = node.children[idx]\n        if node.isEnd {\n            if dfs(word, i+1, count+1, visited, root) {\n                return true\n            }\n        }\n    }\n    return false\n}",
