export function NumberOfPeopleAwareOfASecretProblemSimulation() {
  const approaches: ProblemApproach[] = [
    {
      id: "solution",
      label: "Solution",
      templates: NumberOfPeopleAwareOfASecretTemplates,
      generateSteps: (e: any) => {
        const recorded = generateNumberOfPeopleAwareOfASecretSteps(e) as any[];
        return recorded.map((r) => ({
          id: r.id,
          explanation: r.description,
          variables: r.variables,
          data: r.visualState,
        }));
      },
      renderVisual: (step: ProblemStep) => {
        const visualState = step.data || {};
        const { elements, pointers } = elementsFromVisualState(visualState);
        return (
          <div className="w-full flex flex-col items-center justify-center">
            <ArrayVisualizer elements={elements} pointers={pointers} height={260} />
          </div>
        );
      },
    },
  ];

  return (
    <ProblemViewerShell
      title="Number of People Aware of a Secret"
      slug="number-of-people-aware-of-a-secret"
      approaches={approaches}
      presets={NumberOfPeopleAwareOfASecretPresets}
      formatInputDisplay={formatGenericInput}
    />
  );
}
